<template><view class="page"><PageHead title="我的收藏"/><view class="content"><view class="tabs row"><button class="btn light" @click="kind='STORE'">收藏店铺</button><button class="btn light" @click="kind='PRODUCT'">常点菜品</button></view><view v-if="error" class="card" @click="load">{{error}} · 重试</view><view v-for="p in rows" :key="p.id" class="card between"><view @click="go('store/index?id='+(kind==='STORE'?p.id:p.store_id))"><view class="bold">{{p.name}}</view><view class="small muted">{{kind==='STORE'?p.zone:p.store_name}}</view><view v-if="kind==='PRODUCT'" class="small">¥{{money(p.price)}} · {{p.store_active===0?'店铺休息':p.unavailable_reason||'点击查看当前规格和库存'}}</view><text v-else-if="p.active===0" class="small">店铺休息中</text></view><button size="mini" @click="toggleFavorite(kind,p.id)">取消收藏</button></view><view v-if="!rows.length&&!error" class="empty">还没有收藏，去店铺点亮星标吧</view></view></view></template>
<script setup>
import {ref,computed} from 'vue';import {onShow} from '@dcloudio/uni-app';import PageHead from '../../components/PageHead.vue';import {go,money,ensureLogin} from '../../lib/api';import {favorites,loadFavorites,toggleFavorite} from '../../lib/favorites';const kind=ref('STORE'),error=ref(''),rows=computed(()=>kind.value==='STORE'?favorites.stores:favorites.products);async function load(){try{error.value='';await ensureLogin();await loadFavorites()}catch(e){error.value=e.message}}onShow(load)
</script>
